import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"中孚豚魚吉","description":"周易集解 - 中孚豚魚吉","frontmatter":{"title":"中孚豚魚吉","description":"周易集解 - 中孚豚魚吉"},"headers":[],"relativePath":"classics/jijie/061.md","filePath":"classics/jijie/061.md"}'),l={name:"classics/jijie/061.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="中孚豚魚吉" tabindex="-1">中孚豚魚吉 <a class="header-anchor" href="#中孚豚魚吉" aria-label="Permalink to “中孚豚魚吉”">​</a></h1><h2 id="中孚豚魚吉-1" tabindex="-1">中孚豚魚吉 <a class="header-anchor" href="#中孚豚魚吉-1" aria-label="Permalink to “中孚豚魚吉”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>中孚豚魚吉。利涉大川。利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>虞翻曰：訟四之初也。坎孚象在中，謂二也，故稱中孚。此當從四陽二陰之例。遯陰未及三，而大壯陽已至四，故從訟來。二在訟時，體離為鶴，在坎陰中，有｢鳴鶴在陰｣之義也。</p><p>案：坎為豕。訟四降初，折坎稱豚。初陰升四，體巽為魚。中二，孚信也。謂二變應五，化坤成邦，故信及豚魚，吉矣。虞氏以三至上體遯，便以豚魚為遯魚，雖生曲象之異見，乃失化邦之中信也。</p><p>虞翻曰：坎為大川。謂二已化邦，三利出涉坎。得正，體渙。渙，舟檝象，故｢利涉大川，乘木舟虛也｣。</p><p>虞翻曰：謂二利之正，而應五也。中孚以利貞，乃應於天也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：中孚，柔在內而剛得中，說而巽孚，乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>王肅曰：三、四在內，二、五得中，兌說而巽順，故孚也。</p><p>虞翻曰：二化應五成坤，坤為邦，故化邦也。</p><p>虞翻曰：豚魚，謂四、三也。艮為山陸，豚所處。三為兌澤，魚所在。豚者卑賤，魚者幽隱，中信之道，皆及之矣。</p><p>王肅曰：中孚之象，外實內虛，有似可乘虛木之舟也。</p><p>虞翻曰：訟乾為天，二動應乾，故｢乃應乎天也｣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上有風，中孚。君子以議獄緩死。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：流風令於上，布澤惠於下，中孚之象也。</p><p>虞翻曰：君子，謂乾也。訟坎為獄；震為議，為緩；坤為死。乾四之初，則二出坎獄。兌說震喜，坎獄不見，故「議獄緩死」也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，虞吉，有它不燕。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>荀爽曰：震，宴也。初應於四，宜自安虞，無意於四則吉，故曰虞吉也。四者乘五，有它意於四則不安，故曰｢有它不燕｣也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：初九虞吉，志未變也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：初位潛藏，未得變而應四也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：靡，共也。震為鳴；訟離為鶴，坎為陰夜，鶴知夜半。故｢鳴鶴在陰｣。二動成坤體，益互艮為子，震巽同聲者相應，故｢其子和之｣。坤為身故稱｢我｣。吾，謂五也。離為爵，爵，位也。坤為邦國，五在艮，閽寺庭闕之象。故稱｢好爵｣。五利二變之正應以故｢吾與爾靡之｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：其子和之，中心願也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎為心，動得正應五，故｢中心願也｣。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，得敵，或鼓或罷，或泣或歌。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>荀爽曰：三四俱陰，故稱得也。四得位，有位，故鼓而歌。三失位，無實。故罷而泣之也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：或鼓或罷，位不當也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：三四俱陰，金水異性，敵之謂也。以陰居陽，自疆而進，進而礙敵。故或鼓也。四履正位，非三敵所尅，故｢或罷｣也。不勝而退，懼見侵陵，故｢或泣｣也。四履謙巽，不報讐敵，故或歌也。歌泣無恆，位不當也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，月幾望，馬匹亡，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：訟坎為月，離為日。兌西震東。月在兌二，離為震三，日月象對。故｢月幾望｣。乾坎兩馬匹，初四易位，震為奔走，體遯山中，乾坎不見，故｢馬匹亡｣。初四易位，故｢無咎｣矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：馬匹亡，絕類上也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：訟初之四，體與上絕，故｢絕類上｣也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五：有孚攣如，無咎。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：孚，信也。謂二在坎為孚，巽繩艮手，故｢攣｣。二使化為邦，得正應己，故｢無咎｣也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有孚攣如，位正當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>案：以是成五，有信。攣二使變已，是｢位正當也｣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九：翰音登於天，貞兇。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：巽為雞，應在震，震為音。翰，高也。巽為高，乾為天。故｢翰音登於天｣。失位，故｢貞兇｣。《禮》薦牲，雞稱翰音也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：翰音登於天，何可長也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：窮上失位，信不由中。以此申命，有聲無實。中實內喪，虛華外揚。是｢翰音登天｣也。巽為雞，雞曰翰音。虛音登天，何可久也。</p>',70)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
